<?php require_once __DIR__.'/functions.php';layout_header('Words');$words=load_db()['words'];$cats=array_values(array_unique(array_filter(array_map(fn($w)=>$w['category']??'',$words))));sort($cats);$pos=array_values(array_unique(array_filter(array_map(fn($w)=>$w['part_of_speech']??'',$words))));sort($pos);$catsByLevel=[];foreach($words as $w){$lv=$w['level']??'';$key=(is_numeric($lv)&&(int)$lv>=1&&(int)$lv<=5)?(string)(int)$lv:'Extra';$c=$w['category']??'';if($c===''){continue;}if(!isset($catsByLevel[$key]))$catsByLevel[$key]=[];if(!in_array($c,$catsByLevel[$key],true))$catsByLevel[$key][]=$c;}foreach($catsByLevel as &$cl){sort($cl);}unset($cl);?><script id="levelCatsData" type="application/json"><?=json_encode($catsByLevel,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><div class="panel"><div class="filters"><select id="levelFilter" class="form-select"><option value="">All levels</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option value="Extra">Extra</option></select><select id="catFilter" class="form-select"><option value="">All categories</option><?php foreach($cats as $c):?><option><?=h($c)?></option><?php endforeach;?></select><select id="posFilter" class="form-select"><option value="">All POS</option><?php foreach($pos as $p):?><option><?=h($p)?></option><?php endforeach;?></select><select id="missingFilter" class="form-select"><option value="">Completeness</option><option value="bangla">Missing Bangla</option><option value="audio">Missing Audio</option><option value="examples">Missing Examples</option></select><button class="btn btn-primary ms-auto" id="addWordBtn">Add Word</button></div><div class="table-responsive"><table id="wordsTable" class="table table-hover table-striped w-100"><thead><tr><th>ID</th><th>Level</th><th>Hanzi</th><th>Traditional</th><th>Pinyin</th><th>Bangla Pronunciation</th><th>English</th><th>Bangla</th><th>Category</th><th>POS</th><th>Audio</th></tr><tr class="column-filters"><?php for($i=1;$i<=11;$i++):?><th><input class="form-control form-control-sm" placeholder="Filter"></th><?php endfor;?></tr></thead><tbody><?php foreach($words as $w):$json=h(json_encode($w,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));?><tr data-word='<?=$json?>'><td><?=h($w['id'])?></td><td class="editable-cell" data-field="level"><?=h($w['level'])?></td><td class="hanzi editable-cell" data-field="hanzi"><?=h($w['hanzi'])?></td><td class="editable-cell" data-field="traditional"><?=h($w['traditional'])?></td><td class="editable-cell" data-field="pinyin"><?=h($w['pinyin'])?></td><td class="editable-cell" data-field="bangla_pronunciation"><?=h($w['bangla_pronunciation'])?></td><td class="editable-cell" data-field="english"><?=h($w['english'])?></td><td class="editable-cell" data-field="bangla"><?=h($w['bangla'])?></td><td class="editable-cell" data-field="category"><?=h($w['category'])?></td><td class="editable-cell" data-field="part_of_speech"><?=h($w['part_of_speech'])?></td><td><?php if(!empty($w['audio'])):?><button class="btn btn-sm btn-outline-secondary play-audio" data-src="../<?=h($w['audio'])?>">▶</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/word_modal.php';layout_footer();?>